param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';$root=Split-Path -Parent (Split-Path -Parent $PSCommandPath);$id=[guid]::NewGuid().ToString('N');$dummy=Join-Path ([System.IO.Path]::GetTempPath()) "rawsql-v04-docker-qualification-$id";$events=Join-Path $root "dispatch/candidate-sandbox-events-$id.jsonl";$final=Join-Path $root "dispatch/candidate-sandbox-final-$id.txt";$port=59000+(Get-Random -Minimum 0 -Maximum 500);$name="rawsqlv04q$id";$label="rawsql-v04-qualification=$id";$result=[ordered]@{result='FAIL';kind='PRELAUNCH_INFRA_FAILURE';id=$id;dummyRepository=$dummy;port=$port;containerName=$name;model='gpt-5.6-terra';reasoningEffort='medium';sandbox='workspace-write';eventsPath=$events;finalResponsePath=$final;candidateEvidence=@{};independentEvidence=@{};error=$null}
try{
 New-Item -ItemType Directory -Path $dummy|Out-Null;Set-Content -LiteralPath (Join-Path $dummy 'README.md') -Value '# Docker qualification dummy';Push-Location $dummy;try{git init|Out-Null;git config user.name 'Qualification Fixture';git config user.email 'qualification@example.invalid';git add -A;git commit -m 'dummy baseline'|Out-Null;if((git rev-list --count HEAD).Trim()-ne'1'){throw 'dummy baseline count'};if(@(git remote).Count-ne0){throw 'dummy remote present'}}finally{Pop-Location}
 $readyMarker=Join-Path $dummy '.candidate-db-ready';$verifiedMarker=Join-Path $dummy '.parent-db-verified'
 $prompt=@"
This is a Docker/PostgreSQL capability qualification, not a product task. Work only in this dummy repository. You must personally execute these operations with shell tools and report completion: (1) docker version; (2) prove daemon access; (3) start one isolated PostgreSQL 16 container named $name, labelled $label, mapping host port $port to 5432; (4) wait until it accepts connections; (5) connect with psql; (6) create table qualification_probe(id int primary key, note text); (7) insert exactly (1,'candidate-created'); (8) query and verify that row; (9) create the empty file .candidate-db-ready, wait until .parent-db-verified exists, then (10) stop and remove the container. Do not use Docker resources other than that named/labelled container. Do not alter Git history.
"@
 $proc=Start-Process -FilePath codex -ArgumentList @('exec','--json','-o',$final,'-m','gpt-5.6-terra','-c','model_reasoning_effort="medium"','-s','workspace-write','-C',$dummy,$prompt) -WorkingDirectory $dummy -RedirectStandardOutput $events -RedirectStandardError "$events.err" -PassThru -NoNewWindow
 $deadline=[DateTime]::UtcNow.AddMinutes(12);$observed=$false
 while(-not$proc.HasExited-and[DateTime]::UtcNow-lt$deadline){if(-not$observed-and(Test-Path $readyMarker)){$inspect=&docker inspect $name 2>$null;if($LASTEXITCODE-eq0){$result.independentEvidence.containerCreated=$true;$ready=&docker exec $name pg_isready -U postgres -d postgres 2>$null;$result.independentEvidence.postgresAccepted=$LASTEXITCODE-eq0;$row=&docker exec $name psql -U postgres -d postgres -At -c "select note from qualification_probe where id=1" 2>$null;$result.independentEvidence.expectedSqlState=($LASTEXITCODE-eq0-and$row.Trim()-eq'candidate-created');if($result.independentEvidence.postgresAccepted-and$result.independentEvidence.expectedSqlState){New-Item -ItemType File -Path $verifiedMarker -Force|Out-Null;$observed=$true}}};Start-Sleep -Milliseconds 500}
 if(-not$proc.HasExited){throw 'qualification candidate timed out'};$proc.WaitForExit()
 $eventText=Get-Content -Raw $events;$result.candidateEvidence.threadStarted=$eventText -match 'thread.started';$result.candidateEvidence.turnStarted=$eventText -match 'turn.started';$result.candidateEvidence.dockerVersion=$eventText -match 'docker version';$result.candidateEvidence.postgresAttempted=$eventText -match 'postgres';$result.candidateEvidence.candidateOperationsObserved=($result.candidateEvidence.threadStarted-and$result.candidateEvidence.turnStarted-and$result.candidateEvidence.dockerVersion-and$result.candidateEvidence.postgresAttempted)
 $gone=&docker ps -a --filter "name=^/$name$" --format '{{.ID}}';$result.independentEvidence.teardownCompleted=[string]::IsNullOrWhiteSpace($gone);$result.independentEvidence.portReleased=-not(Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue);$leaks=&docker ps -a --filter "label=$label" --format '{{.ID}}';$result.independentEvidence.noLeakedResources=[string]::IsNullOrWhiteSpace($leaks)
 $all=@($result.candidateEvidence.candidateOperationsObserved,$result.independentEvidence.containerCreated,$result.independentEvidence.postgresAccepted,$result.independentEvidence.expectedSqlState,$result.independentEvidence.teardownCompleted,$result.independentEvidence.portReleased,$result.independentEvidence.noLeakedResources);if($all-notcontains$false){$result.result='PASS';$result.kind='QUALIFICATION_PASS'}else{throw 'candidate-sandbox qualification evidence incomplete'}
}catch{$result.error=$_.Exception.Message}finally{$result|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $OutputPath;if(Test-Path $dummy){Push-Location $dummy;try{if((git rev-list --count HEAD).Trim()-ne'1'){throw 'dummy Git baseline changed'}}finally{Pop-Location}}}
if($result.result-ne'PASS'){exit 1}
